sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var qt = g_form.getValue("query_type");
    if (qt == "1fe207b5536ed210f91579a0a0490e86") {
        g_form.setVisible("project", true);
        g_form.setVisible("sdlc_checklist_item", true);
        g_form.setVisible("environment", false);
        g_form.setVisible("summary", true);
        g_form.setVisible("assigned_to", true);
        g_form.setVisible("description", true);
        g_form.setVisible("supporting_document", true);
        g_form.setVisible("priority", true);
    } else if (qt == "34038339536ed210f91579a0a0490e49") {
        g_form.setVisible("project", false);
        g_form.setVisible("sdlc_checklist_item", false);
        g_form.setVisible("environment", true);
        g_form.setVisible("summary", true);
        g_form.setVisible("assigned_to", true);
        g_form.setVisible("description", true);
        g_form.setVisible("supporting_document", true);
        g_form.setVisible("priority", true);
    }else{
		 g_form.setVisible("project", false);
        g_form.setVisible("sdlc_checklist_item", false);
        g_form.setVisible("environment", false);
        g_form.setVisible("summary", true);
        g_form.setVisible("assigned_to", true);
        g_form.setVisible("description", true);
        g_form.setVisible("supporting_document", true);
        g_form.setVisible("priority", true);
	}

    //Type appropriate comment here, and begin script below

}
